using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.LoyaltyDiscount;

public sealed class LoyaltyDiscountPolicyTests
{
    [Theory]
    [InlineData(LoyaltyTier.Bronze, 1, 0)]
    [InlineData(LoyaltyTier.Bronze, 7, 0)]
    [InlineData(LoyaltyTier.Bronze, 100, 5)]
    [InlineData(LoyaltyTier.Bronze, 10_000, 500)]
    [InlineData(LoyaltyTier.Silver, 7, 0)]
    [InlineData(LoyaltyTier.Silver, 100, 10)]
    [InlineData(LoyaltyTier.Silver, 10_000, 1_000)]
    [InlineData(LoyaltyTier.Gold, 7, 1)]
    [InlineData(LoyaltyTier.Gold, 100, 15)]
    [InlineData(LoyaltyTier.Gold, 10_000, 1_500)]
    public void LoyaltyDiscountIsTierRateOfSubtotalRoundedDownToTheCent(
        LoyaltyTier loyaltyTier,
        int subtotalCents,
        int expectedDiscountCents)
    {
        Assert.Equal(expectedDiscountCents, LoyaltyDiscountPolicy.DiscountCents(subtotalCents, loyaltyTier));
    }
}

