namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int LoyaltyCapCents = 2_000;
    private const int WelcomeCents = 500;
    private const int SummerPercent = 10;
    private const int SummerCapCents = 1_500;

    public static int DiscountCents(int subtotalCents, LoyaltyTier loyaltyTier, string? promoCode = null)
    {
        var loyaltyCents = LoyaltyCents(subtotalCents, loyaltyTier);
        var promoCents = PromoCents(subtotalCents - loyaltyCents, promoCode);
        return Math.Min(subtotalCents, loyaltyCents + promoCents);
    }

    private static int LoyaltyCents(int subtotalCents, LoyaltyTier loyaltyTier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(subtotalCents * RatePercent(loyaltyTier) / 100, LoyaltyCapCents);

    private static int PromoCents(int remainingCents, string? promoCode) => promoCode?.ToUpperInvariant() switch
    {
        "WELCOME5" => WelcomeCents,
        "SUMMER10" => Math.Min(remainingCents * SummerPercent / 100, SummerCapCents),
        _ => 0
    };

    private static int RatePercent(LoyaltyTier loyaltyTier) => loyaltyTier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => throw new ArgumentOutOfRangeException(nameof(loyaltyTier))
    };
}

