namespace CheckoutPricing.Domain;

public static class ShippingFeePolicy
{
    private const int StandardCents = 490;
    private const int ExpressCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public static int FeeCents(int payableTotalCents, LoyaltyTier loyaltyTier, bool express) =>
        express ? ExpressFeeCents(loyaltyTier) : StandardFeeCents(payableTotalCents, loyaltyTier);

    private static int ExpressFeeCents(LoyaltyTier loyaltyTier) =>
        loyaltyTier == LoyaltyTier.Platinum ? 0 : ExpressCents;

    private static int StandardFeeCents(int payableTotalCents, LoyaltyTier loyaltyTier) =>
        loyaltyTier >= LoyaltyTier.Gold || payableTotalCents >= FreeStandardFromCents ? 0 : StandardCents;
}

